import React, { createContext, useContext, useState, useEffect } from 'react';
import Cookies from 'js-cookie';
import logo from '../components/logo.jpg';

// Create the context
const globalContext = createContext();

// Custom hook to access the context
export const useGlobal = () => useContext(globalContext);

export const GlobalProvider = ({ children }) => {
  const [darkMode, setDarkMode] = useState(localStorage.getItem('dark-mode') === 'enabled');
  const [sidebarActive, setSidebarActive] = useState(false);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [userProfile, setUserProfile] = useState(null);
  const [role, setRole] = useState(null);
  const [loading, setLoading] = useState(true); // Added loading state
  const [banners, setBanners] = useState([]); // State to store banners
  // const API_URL = 'http://localhost:5000';
  // const API_URL = 'https://excellence-classses-backend.vercel.app';
  const API_URL = '';
  const token = Cookies.get('x-auth-token');

  const login = () => setIsLoggedIn(true);

  const logout = () => {
    // Clear auth-related data
    setIsLoggedIn(false);
    Cookies.remove('x-auth-token');
    setUserProfile(null);
    setRole(null);
    setLoading(false); // Ensure no indefinite loading
    // Redirect to login page
    window.location.href = '/login';
  };

  // Fetch user profile and banners
  useEffect(() => {
    const fetchUserProfile = async () => {
      if (token) {
        try {
          const response = await fetch(`${API_URL}/api/auth/profile`, {
            headers: { 'x-auth-token': token },
          });

          if (response.ok) {
            const data = await response.json();
            setUserProfile(data.profile);
            setRole(data.profile.role);
            setIsLoggedIn(true);
          } else {
            throw new Error('Failed to fetch profile');
          }
        } catch (error) {
          console.error('Error loading user profile:', error);
          logout(); // Log out on error
        } finally {
          setLoading(false); // Stop loading regardless of success or failure
        }
      } else {
        setLoading(false); // Stop loading if no token is found
      }
    };

    const fetchBanners = async () => {
      if (token) {
        try {
          const response = await fetch(`${API_URL}/api/banners`, {
            headers: { 'x-auth-token': token },
          });
          
          if (response.ok) {
            const data = await response.json();
            setBanners(data); // Assuming the response contains the banners array
          } else {
            throw new Error('Failed to fetch banners');
          }
        } catch (error) {
          console.error('Error fetching banners:', error);
        }
      }
    };

    fetchUserProfile();
    fetchBanners();
  }, [token, API_URL]);

  useEffect(() => {
    // Sync dark mode with the body class
    document.body.classList.toggle('dark', darkMode);
  }, [darkMode]);

  const toggleDarkMode = () => {
    const newDarkMode = !darkMode;
    setDarkMode(newDarkMode);
    localStorage.setItem('dark-mode', newDarkMode ? 'enabled' : 'disabled');
  };

  const toggleSidebar = () => setSidebarActive((prev) => !prev);
  const closeSidebar = () => setSidebarActive(false);
console.log(banners)
  return (
    <globalContext.Provider
      value={{
        darkMode,
        toggleDarkMode,
        sidebarActive,
        toggleSidebar,
        closeSidebar,
        isLoggedIn,
        login,
        logout,
        userProfile,
        setUserProfile,
        role,
        setRole,
        API_URL,
        isLoading: loading, // Expose the loading state
        banners, // Expose the banners state
      }}
    >
      {loading ? (
        <>
          <div style={{ display: 'flex', justifyContent: 'center', height: '100vh', flexDirection: 'column', alignItems: 'center', background: 'white' }}>
            <img src={logo} alt="" height={100} />
            <br />
            <br />
            <br />
            <div className="loader" style={{ width: '40px', height: '40px' }}></div>
          </div>
        </>
      ) : (
        children
      )}
    </globalContext.Provider>
  );
};
