import React, { useState, useEffect } from 'react';
import axios from 'axios';

const Quiz = () => {
  const [questions, setQuestions] = useState([]);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [score, setScore] = useState(0);
  const [loading, setLoading] = useState(true);
  const [quizFinished, setQuizFinished] = useState(false); // New state to track quiz completion

  useEffect(() => {
    axios.get('https://opentdb.com/api.php?amount=10&category=19&difficulty=easy')
      .then((response) => {
        setQuestions(response.data.results);
        setLoading(false);
      })
      .catch((error) => console.error('Error fetching data:', error));
  }, []);

  const handleAnswerClick = (isCorrect) => {
    if (isCorrect) {
      setScore(score + 1);
    }
    if (currentQuestionIndex < questions.length - 1) {
      setCurrentQuestionIndex(currentQuestionIndex + 1);
    } else {
      setQuizFinished(true); // Set quiz to finished when all questions are answered
    }
  };

  const handlePlayAgain = () => {
    setScore(0);
    setCurrentQuestionIndex(0);
    setQuizFinished(false);
    setLoading(true);
    axios.get('https://opentdb.com/api.php?amount=5&type=multiple')
      .then((response) => {
        setQuestions(response.data.results);
        setLoading(false);
      })
      .catch((error) => console.error('Error fetching data:', error));
  };

  if (loading) {
    return             <div className="loader-container">
    <div className="loader"></div>
  </div>;
  }

  if (quizFinished) {
    return (
      <div className="quiz-container">
        <h2>Quiz Completed!</h2>
        <p>Your score is {score} out of {questions.length}</p>
        <button className="play-again-btn" onClick={handlePlayAgain}>Play Again</button>
      </div>
    );
  }

  const currentQuestion = questions[currentQuestionIndex];
  const shuffledAnswers = [...currentQuestion.incorrect_answers, currentQuestion.correct_answer]
    .sort(() => Math.random() - 0.5);

  return (
    <div className="quiz-container">
      <div className="question">
        <h2>{currentQuestion.question}</h2>
      </div>
      <div className="answers">
        {shuffledAnswers.map((answer, index) => (
          <button
            key={index}
            className="answer-btn"
            onClick={() => handleAnswerClick(answer === currentQuestion.correct_answer)}
          >
            {answer}
          </button>
        ))}
      </div>
      <div className="score">
        <p>Score: {score}</p>
      </div>
    </div>
  );
};

export default Quiz;
