import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useGlobal } from "../context/GlobalContext";

// Helper function to get the authentication token from cookies
const getAuthToken = () => {
  
  const cookieString = document.cookie.split('; ').find(row => row.startsWith('x-auth-token='));
  return cookieString ? cookieString.split('=')[1] : null;
};

const CreateOfflineTestForm = () => {
  const { API_URL } = useGlobal()
  const [title, setTitle] = useState('');
  const [subject, setSubject] = useState('');
  const [testDate, setTestDate] = useState('');
  const [startTime, setStartTime] = useState('');
  const [batchId, setBatchId] = useState('');
  const [durationMinutes, setDurationMinutes] = useState('');
  const [classroom, setClassroom] = useState('');
  const [additionalNotes, setAdditionalNotes] = useState('');
  const [totalMarks, setTotalMarks] = useState('');  // Added state for totalMarks
  const [batches, setBatches] = useState([]);
  const [message, setMessage] = useState(null);

  // Fetch batch data from the server
  useEffect(() => {
    const fetchBatches = async () => {
      const token = getAuthToken();
      if (!token) {
        setMessage('Authentication token not found.');
        return;
      }
      try {
        const response = await axios.get(`${API_URL}/api/standard/batch`, {
          headers: { 'x-auth-token': token }
        });
        setBatches(response.data);
      } catch (error) {
        console.error('Error fetching batches:', error);
        setMessage('Error fetching batch data.');
      }
    };
    fetchBatches();
  }, []);

  // Handle form submission
  const handleSubmit = async (e) => {
    e.preventDefault();
    const token = getAuthToken();
    if (!token) {
      setMessage('Authentication token not found.');
      return;
    }

    try {
      const response = await axios.post(
        `${API_URL}/api/offline/tests/createOfflineTest`,
        {
          title,
          subject,
          testDate,
          startTime,
          batch: batchId,
          durationMinutes,
          classroom,
          additionalNotes,
          totalMarks  // Added totalMarks to the request data
        },
        {
          headers: { 'x-auth-token': token }
        }
      );

      setMessage('Test created successfully');
      // Clear form fields
      setTitle('');
      setSubject('');
      setTestDate('');
      setStartTime('');
      setBatchId('');
      setDurationMinutes('');
      setClassroom('');
      setAdditionalNotes('');
      setTotalMarks('');  // Reset totalMarks field
    } catch (error) {
      console.error('Error creating test:', error);
      setMessage('Error creating test.');
    }
  };

  return (
    <div className="offlineTestForm">
      <h2>Create Offline Test</h2>
      {message && <div className="message">{message}</div>}
      <div className="form-container">
        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label htmlFor="title">Title:</label>
            <input type="text" id="title" value={title} onChange={(e) => setTitle(e.target.value)} required />
          </div>

          <div className="form-group">
            <label htmlFor="batch">Batch:</label>
            <select id="batch" value={batchId} onChange={(e) => setBatchId(e.target.value)} required>
              <option value="">Select a batch</option>
              {batches.map((batch) => (
                <option key={batch._id} value={batch._id}>
                  {batch.name} - {batch.standard.name}
                </option>
              ))}
            </select>
          </div>

          <div className="form-group">
            <label htmlFor="subject">Subject:</label>
            <input type="text" id="subject" value={subject} onChange={(e) => setSubject(e.target.value)} required />
          </div>

          <div className="form-group">
            <label htmlFor="testDate">Test Date:</label>
            <input type="date" id="testDate" value={testDate} onChange={(e) => setTestDate(e.target.value)} required />
          </div>

          <div className="form-group">
            <label htmlFor="startTime">Start Time:</label>
            <input type="time" id="startTime" value={startTime} onChange={(e) => setStartTime(e.target.value)} required />
          </div>

          <div className="form-group">
            <label htmlFor="durationMinutes">Duration (Minutes):</label>
            <input type="number" id="durationMinutes" value={durationMinutes} onChange={(e) => setDurationMinutes(e.target.value)} required />
          </div>

          <div className="form-group">
            <label htmlFor="classroom">Classroom:</label>
            <input type="text" id="classroom" value={classroom} onChange={(e) => setClassroom(e.target.value)} />
          </div>

          <div className="form-group">
            <label htmlFor="additionalNotes">Additional Notes:</label>
            <textarea id="additionalNotes" value={additionalNotes} onChange={(e) => setAdditionalNotes(e.target.value)} />
          </div>

          <div className="form-group">
            <label htmlFor="totalMarks">Total Marks:</label>
            <input
              type="number"
              id="totalMarks"
              value={totalMarks}
              onChange={(e) => setTotalMarks(e.target.value)}
              required
            />
          </div>

          <button type="submit">Create Test</button>
        </form>
      </div>
    </div>
  );
};

export default CreateOfflineTestForm;
