import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import { Link } from 'react-router-dom';
import { useGlobal } from "../context/GlobalContext";

const StaffListByRole = () => {
    const { API_URL } = useGlobal()

    const [roles, setRoles] = useState(['teacher', 'admin']); // Define more roles if needed
    const [statuses] = useState(['active', 'resigned', 'absconded', 'postponed', 'suspended', 'withdrawn']);
    const [staff, setStaff] = useState([]);
    const [selectedRole, setSelectedRole] = useState('teacher'); // Default role
    const [selectedStatus, setSelectedStatus] = useState('active'); // Default status
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [searchQuery, setSearchQuery] = useState('');
    const [currentPage, setCurrentPage] = useState(1);
    const [totalPages, setTotalPages] = useState(1);

    const getTokenFromCookies = () => {
        const cookieValue = document.cookie.split('; ').find(row => row.startsWith('x-auth-token='));
        return cookieValue ? cookieValue.split('=')[1] : null;
    };

    const token = getTokenFromCookies();

    // Fetch staff based on role, status, and search query
    const fetchStaffByRole = async (page = 1, isSearch = false) => {
        setLoading(true);
        setError('');

        try {
            const url = isSearch && searchQuery
                ? `${API_URL}/api/users/search-users?role=${selectedRole}&status=${selectedStatus}&page=${page}&query=${searchQuery}`
                : `${API_URL}/api/users/profiles/${selectedRole}?status=${selectedStatus}&page=${page}`;

            const response = await axios.get(url, {
                headers: { 'x-auth-token': token }
            });

            setStaff(prevStaff => {
                const newStaff = response.data.users;
                return isSearch 
                    ? newStaff // Replace staff list on search
                    : [...prevStaff, ...newStaff.filter(member => 
                        !prevStaff.some(prevMember => prevMember._id === member._id)
                    )];
            });

            setTotalPages(response.data.totalPages);
            setCurrentPage(page);
        } catch (err) {
            console.error("Error fetching staff data:", err);
            setError("Failed to load staff data");
            setStaff([]);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        if (searchQuery === '') {
            fetchStaffByRole(currentPage, false); // Fetch all staff for selected role and status
        }
    }, [selectedRole, selectedStatus, token, currentPage]);

    const handleRoleChange = (e) => {
        const role = e.target.value;
        setSelectedRole(role);
        setStaff([]); // Reset staff list when role changes
        setCurrentPage(1); // Reset to first page
        setError('');
        setTotalPages(1); // Reset total pages to reload data
    };

    const handleStatusChange = (e) => {
        const status = e.target.value;
        setSelectedStatus(status);
        setStaff([]); // Reset staff list when status changes
        setCurrentPage(1); // Reset to first page
        setError('');
        setTotalPages(1); // Reset total pages to reload data
    };

    const handleSearchChange = (e) => {
        setSearchQuery(e.target.value);
    };

    const handleSearchButtonClick = () => {
        setStaff([]); // Clear current staff list to load new results
        setCurrentPage(1); // Reset to first page
        fetchStaffByRole(1, searchQuery.length > 0); // Fetch staff based on search query
    };

    const handleStaffStatusChange = async (staffId, newStatus) => {
        setLoading(true);
        try {
            await axios.put(`${API_URL}/api/auth/status/${staffId}`, { status: newStatus }, {
                headers: { 'x-auth-token': token }
            });
            setStaff((prevStaff) =>
                prevStaff.map((member) =>
                    member._id === staffId ? { ...member, status: newStatus } : member
                )
            );
            toast.success('Status updated successfully!');
        } catch (err) {
            console.error("Error updating status:", err);
            toast.error('Failed to update status');
        } finally {
            setLoading(false);
        }
    };

    const loadMoreStaff = () => {
        if (currentPage < totalPages) {
            setCurrentPage(prevPage => prevPage + 1);
        }
    };

    return (
        <div className="container mt-5 attendance-container">
            <h2 className="text-center mb-4 title">Staff List by Role and Status</h2>

            <div className="mb-3 role-container">
                <label htmlFor="role" className="form-label">Select Role:</label>
                <select
                    id="role"
                    className="form-control date-input"
                    value={selectedRole}
                    onChange={handleRoleChange}
                >
                    {roles.map(role => (
                        <option key={role} value={role}>{role}</option>
                    ))}
                </select>
            </div>

            <div className="mb-3 status-container">
                <label htmlFor="status" className="form-label">Select Status:</label>
                <select
                    id="status"
                    className="form-control date-input"
                    value={selectedStatus}
                    onChange={handleStatusChange}
                >
                    {statuses.map(status => (
                        <option key={status} value={status}>{status}</option>
                    ))}
                </select>
            </div>

            <div className="mb-3">
                <input
                    type="text"
                    className="form-control"
                    placeholder="Search by name..."
                    onChange={handleSearchChange}
                    value={searchQuery}
                />
                <button className="btn btn-primary mt-2" onClick={handleSearchButtonClick}>
                    Search
                </button>
            </div>

            {error ? (
                <p className="text-danger">{error}</p>
            ) : loading ? (
                <div className="loader-container">
                <div className="loader"></div>
              </div>
            ) : staff.length > 0 ? (
                <>
                    <table className="table attendance-table">
                        <thead>
                            <tr>
                                <th>Staff Name</th>
                                <th>Contact No.</th>
                                <th>Salary (INR)</th>
                                <th>Status</th>
                            </tr>
                        </thead>
                        <tbody>
                            {staff.map((member) => (
                                <tr key={member._id}>
                                    <td><Link style={{ color: "black" }} to={`/loggedin/profile/${member._id}`}>{member.name}</Link></td>
                                    <td><Link style={{ color: "black" }} to={`tel:${member.personalContactNumber}`}>{member.personalContactNumber}</Link></td>
                                    <td>₹{member.salary} / {`${member.salaryType}`}</td>
                                    <td>
                                        <select
                                            value={member.status}
                                            onChange={(e) => handleStaffStatusChange(member._id, e.target.value)}
                                            className="form-control"
                                        >
                                            {statuses.map(statusOption => (
                                                <option key={statusOption} value={statusOption}>{statusOption}</option>
                                            ))}
                                        </select>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                    {currentPage < totalPages && (
                        <div className="text-center">
                            <button className="btn btn-primary" onClick={loadMoreStaff}>
                                Load More
                            </button>
                        </div>
                    )}
                </>
            ) : (
                <p className="text-center">No staff data found for this role and status</p>
            )}

            <ToastContainer />
            <style>
                {`
                    .loader-container {
                        display: flex;
                        justify-content: center;
                        align-items: center;
                        height: 100px;
                    }
                `}
            </style>
        </div>
    );
};

export default StaffListByRole;
