import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Link } from 'react-router-dom';
import { useGlobal } from '../context/GlobalContext';
import HallTicket from './HallTicket';

// Function to get cookie value by name
const getCookie = (name) => {
    const value = `; ${document.cookie}`;
    const parts = value.split(`; ${name}=`);
    if (parts.length === 2) return parts.pop().split(';').shift();
    return null;
};

const OfflineTests = () => {
    const { role, userProfile, API_URL } = useGlobal(); // User info from context
    const [tests, setTests] = useState([]);
    const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split("T")[0]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState("");
    const [showHallTicket, setShowHallTicket] = useState(false); // State to toggle HallTicket modal

    // Pagination states
    const [currentPage, setCurrentPage] = useState(1);
    const [hasMore, setHasMore] = useState(true);

    // Function to fetch tests by date with pagination and x-auth-token from cookies
    const fetchTests = async (date, page = 1) => {
        setLoading(true);
        setError("");
        try {
            const token = getCookie("x-auth-token");
            if (!token) {
                setError("Authorization token is missing.");
                setLoading(false);
                return;
            }

            const response = await axios.get(`${API_URL}/api/offline/tests`, {
                headers: { "x-auth-token": token },
                params: { date, page }, // Include date and page in params
            });

            const fetchedTests = response.data.tests;
            const totalDocuments = response.data.totalDocuments;
            const totalPages = response.data.totalPages;

            // Append new tests to the list ensuring uniqueness
            setTests((prevTests) => {
                const uniqueTests = [
                    ...prevTests,
                    ...fetchedTests.filter(
                        (test) => !prevTests.some((existingTest) => existingTest._id === test._id)
                    ),
                ];
                return uniqueTests;
            });

            // Update pagination state
            setHasMore(page < totalPages);
        } catch (err) {
            setError("Error fetching tests. Please try again.");
        } finally {
            setLoading(false);
        }
    };

    // Fetch all tests from today on component mount
    useEffect(() => {
        fetchTests(selectedDate);
    }, []);

    const handleLoadMore = () => {
        const nextPage = currentPage + 1;
        setCurrentPage(nextPage);
        fetchTests(selectedDate, nextPage);
    };

    return (
        <div className="offline-tests-container">
            <h2>Offline Tests</h2>

            {/* Date Picker to select test date */}
            <div className="date-picker">
                <label htmlFor="testDate">Select Date: </label>
                <input
                    type="date"
                    id="testDate"
                    value={selectedDate}
                    onChange={(e) => {
                        setSelectedDate(e.target.value);
                        setTests([]); // Clear previous tests
                        setCurrentPage(1); // Reset to page 1
                        setHasMore(true); // Reset pagination state
                        fetchTests(e.target.value); // Fetch tests for new date
                    }}
                />
                <button
                    className="apply-changes-btn"
                    onClick={() => {
                        setTests([]); // Clear previous tests
                        setCurrentPage(1); // Reset to page 1
                        setHasMore(true); // Reset pagination state
                        fetchTests(selectedDate); // Fetch tests for selected date
                    }}
                >
                    Apply Changes
                </button>
            </div>

            {tests.length > 0 && (
                <button
                    className="view-result-btn"
                    onClick={() => setShowHallTicket(true)} // Show HallTicket modal
                >
                    View Hall Tickets
                </button>
            )}
            <br />
            <br />

            {/* Loader */}
            {loading && (
                <div className="loader-container">
                    <div className="loader"></div>
                </div>
            )}

            {error && <p className="error-text">{error}</p>}

            {/* Render list of tests */}
            {tests.length > 0 ? (
                <div className="tests-list">
                    {tests.map((test) => (
                        <div key={test._id} className="test-card">
                            <h3 className="test-title">{test.title}</h3>
                            <div className="test-info">
                                <div>
                                    <p><span>Batch:</span> {test.batch?.name || 'N/A'}</p>
                                    <p><span>Standard:</span> {test.batch?.standard?.name || 'N/A'}</p>
                                    <p><span>Subject:</span> {test.subject}</p>
                                </div>
                                <div>
                                    <p><span>Date:</span> {new Date(test.testDate).toLocaleDateString()}</p>
                                    <p><span>Start Time:</span> {test.startTime}</p>
                                    <p><span>Duration:</span> {test.durationMinutes} minutes</p>
                                </div>
                                <div>
                                    <p><span>Classroom:</span> {test.classroom}</p>
                                    <p><span>Additional Notes:</span> {test.additionalNotes}</p>
                                </div>
                            </div>

                            {/* View Result Button */}
                            <Link to={`/loggedin/test/TestsResults/${test._id}`}>
                                <button className="view-result-btn">View Result</button>
                            </Link> &nbsp;
                            {(role === 'admin' || role === 'teacher') &&
                                !test.resultDeclared && (
                                    <Link to={`/loggedin/test/addStudentmarks/${test._id}`}>
                                        <button className="view-result-btn">Add Marks</button>
                                    </Link>
                                )}
                        </div>
                    ))}
                </div>
            ) : (
                !loading && <p className="no-tests-message">No tests found for the selected date.</p>
            )}

            {/* Load More Button */}
            {hasMore && !loading && (
                <button
                    className="load-more-btn"
                    onClick={handleLoadMore}
                >
                    Load More
                </button>
            )}

            {/* Hall Ticket Modal */}
            {showHallTicket && (
                <div className="modal-overlay">
                    <div className="modal-content">
                        <button className="close-btn" onClick={() => setShowHallTicket(false)}>
                            &times;
                        </button>
                        <div style={{ overflowX: "auto" }}>
                            <HallTicket testPaper={tests} /> {/* Pass user profile to HallTicket */}
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default OfflineTests;
