import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { toast } from 'react-toastify';
import Cookies from "js-cookie";
import { useGlobal } from "../context/GlobalContext";

const AdminSalaryManager = () => {
    const { API_URL } = useGlobal();

    const getAuthToken = () => Cookies.get("x-auth-token");

    const [salaries, setSalaries] = useState([]);
    const [updatedSalaries, setUpdatedSalaries] = useState([]);
    const [month, setMonth] = useState('');
    const [year, setYear] = useState('');
    const [loading, setLoading] = useState(false);
    const [accessDenied, setAccessDenied] = useState(false); // State to handle access denial

    useEffect(() => {
        const currentDate = new Date();
        const defaultMonth = currentDate.getMonth() === 0 ? 12 : currentDate.getMonth();
        const defaultYear = currentDate.getMonth() === 0 ? currentDate.getFullYear() - 1 : currentDate.getFullYear();
        setMonth(defaultMonth);
        setYear(defaultYear);

        fetchSalaries(defaultMonth, defaultYear);
    }, []);

    const fetchSalaries = async (monthToFetch = month, yearToFetch = year) => {
        try {
            setLoading(true);
            setAccessDenied(false); // Reset access denial state
            const response = await axios.get(
                `${API_URL}/api/salary/all-salaries?month=${monthToFetch}&year=${yearToFetch}`,
                {
                    headers: {
                        "x-auth-token": getAuthToken(),
                    },
                }
            );
            setSalaries(response.data.data);
        } catch (error) {
            if (error.response?.status === 403) {
                setAccessDenied(true); // Set access denied state
            } else {
                toast.error('Failed to fetch salary details.');
            }
        } finally {
            setLoading(false);
        }
    };

    const handleInputChange = (index, field, value) => {
        const updated = [...salaries];
        updated[index][field] = value;
        setSalaries(updated);

        const existingEntryIndex = updatedSalaries.findIndex((item) => item.salaryId === updated[index]._id);

        const updatedEntry = {
            salaryId: updated[index]._id,
            paymentMethod: updated[index].paymentMethod,
            status: updated[index].status,
            salary: updated[index].salary,
            [field]: value,
        };

        if (existingEntryIndex !== -1) {
            const updatedEntries = [...updatedSalaries];
            updatedEntries[existingEntryIndex] = updatedEntry;
            setUpdatedSalaries(updatedEntries);
        } else {
            setUpdatedSalaries([...updatedSalaries, updatedEntry]);
        }
    };

    const handleBulkUpdate = async () => {
        if (updatedSalaries.length === 0) {
            toast.warn('No changes to update.');
            return;
        }

        try {
            setLoading(true);
            const response = await axios.put(
                `${API_URL}/api/salary/update-payment-details`,
                {
                    updates: updatedSalaries,
                },
                {
                    headers: {
                        "x-auth-token": getAuthToken(),
                    },
                }
            );
            toast.success(response.data.message);
            fetchSalaries();
            setUpdatedSalaries([]);
        } catch (error) {
            toast.error('Failed to update salary details.');
        } finally {
            setLoading(false);
        }
    };

    if (accessDenied) {
        // Access Denied Page
        return (
            <div
                style={{
                    display: 'flex',
                    justifyContent: 'center',
                    alignItems: 'center',
                    height: '100vh',
                    fontFamily: 'Arial, sans-serif',
                    backgroundColor: '#f9f9f9',
                }}
            >
                <h1 style={{ color: '#e74c3c', textAlign: 'center' }}>Access Denied</h1>
            </div>
        );
    }

    return (
        <div style={{ padding: '20px', fontFamily: 'Arial, sans-serif', backgroundColor: '#f9f9f9', minHeight: '100vh' }}>
            <h1 style={{ textAlign: 'center', color: '#333', marginBottom: '20px' }}>Admin Salary Manager</h1>
            <div
                style={{
                    marginBottom: '20px',
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    gap: '10px',
                    flexWrap: 'wrap',
                }}
            >
                <label>
                    <span style={{ fontWeight: 'bold', marginRight: '5px' }}>Select Month:</span>
                    <select
                        value={month}
                        onChange={(e) => setMonth(e.target.value)}
                        style={{
                            padding: '5px',
                            border: '1px solid #ccc',
                            borderRadius: '4px',
                            minWidth: '120px',
                        }}
                    >
                        <option value="">--Select Month--</option>
                        {Array.from({ length: 12 }, (_, i) => (
                            <option key={i + 1} value={i + 1}>
                                {new Date(0, i).toLocaleString('default', { month: 'long' })}
                            </option>
                        ))}
                    </select>
                </label>
                <label>
                    <span style={{ fontWeight: 'bold', marginRight: '5px' }}>Select Year:</span>
                    <input
                        type="number"
                        value={year}
                        onChange={(e) => setYear(e.target.value)}
                        placeholder="Enter Year"
                        style={{
                            padding: '5px',
                            border: '1px solid #ccc',
                            borderRadius: '4px',
                            minWidth: '120px',
                        }}
                    />
                </label>
                <button
                    onClick={() => fetchSalaries()}
                    style={{
                        padding: '10px 20px',
                        backgroundColor: '#5a4d91',
                        color: '#fff',
                        border: 'none',
                        borderRadius: '4px',
                        cursor: 'pointer',
                        fontSize: '16px',
                    }}
                >
                    Search
                </button>
            </div>

            {loading ? (
                <div style={{ textAlign: 'center', margin: '20px' }}>
                    <span
                        style={{
                            fontSize: '18px',
                            color: '#555',
                        }}
                    >
                        Loading...
                    </span>
                </div>
            ) : salaries.length === 0 ? (
                <div style={{ textAlign: 'center', margin: '20px', fontSize: '18px', color: '#555' }}>
                    No data available for the selected month and year.
                </div>
            ) : (
                <table
                    style={{
                        width: '100%',
                        borderCollapse: 'collapse',
                        marginBottom: '20px',
                        boxShadow: '0 0 10px rgba(0, 0, 0, 0.1)',
                    }}
                >
                    <thead>
                        <tr style={{ backgroundColor: '#5a4d91', color: '#fff' }}>
                            <th style={{ padding: '10px', textAlign: 'left' }}>Name</th>
                            <th style={{ padding: '10px', textAlign: 'left' }}>Salary</th>
                            <th style={{ padding: '10px', textAlign: 'left' }}>Payment Method</th>
                            <th style={{ padding: '10px', textAlign: 'left' }}>Status</th>
                        </tr>
                    </thead>
                    <tbody>
                        {salaries.map((salary, index) => (
                            <tr key={salary._id} style={{ backgroundColor: index % 2 === 0 ? '#f3f3f3' : '#fff' }}>
                                <td style={{ padding: '10px' }}>{salary.user.name} ({salary.user.role})</td>
                                <td style={{ padding: '10px' }}>
                                    <input
                                        type="number"
                                        value={salary.salary}
                                        onChange={(e) => handleInputChange(index, 'salary', e.target.value)}
                                        style={{ padding: '5px', border: '1px solid #ccc', borderRadius: '4px' }}
                                    />
                                </td>
                                <td style={{ padding: '10px' }}>
                                    <select
                                        value={salary.paymentMethod}
                                        onChange={(e) => handleInputChange(index, 'paymentMethod', e.target.value)}
                                        style={{ padding: '5px', border: '1px solid #ccc', borderRadius: '4px' }}
                                    >
                                        <option value="Bank Transfer">Bank Transfer</option>
                                        <option value="Cash">Cash</option>
                                        <option value="Cheque">Cheque</option>
                                    </select>
                                </td>
                                <td style={{ padding: '10px' }}>
                                    <select
                                        value={salary.status}
                                        onChange={(e) => handleInputChange(index, 'status', e.target.value)}
                                        style={{ padding: '5px', border: '1px solid #ccc', borderRadius: '4px' }}
                                    >
                                        <option value="Paid">Paid</option>
                                        <option value="Pending">Pending</option>
                                    </select>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            )}

            <button
                onClick={handleBulkUpdate}
                style={{
                    padding: '10px 20px',
                    backgroundColor: '#e74c3c',
                    color: '#fff',
                    border: 'none',
                    borderRadius: '4px',
                    cursor: 'pointer',
                    fontSize: '16px',
                }}
            >
                Update Salaries
            </button>
        </div>
    );
};

export default AdminSalaryManager;
