import React, { useEffect, useState, useCallback } from 'react';
import { Link, useParams } from 'react-router-dom';
import axios from 'axios';
import { useGlobal } from '../context/GlobalContext';
import UpdateProfileForm from '../components/UpdateProfileForm'; // Import the update form component
import { ToastContainer, toast } from 'react-toastify'; // Import toast notifications
import 'react-toastify/dist/ReactToastify.css';


const Profile = () => {
  const { userProfile,API_URL } = useGlobal(); // Global context for the logged-in user's profile
  const { id } = useParams(); // Extracting the user ID from the URL parameters
  const [userProfileById, setUserProfileById] = useState(null);
  const [loading, setLoading] = useState(true); // Loading state
  const [isEditing, setIsEditing] = useState(false); // State for edit mode
  const [updateSuccess, setUpdateSuccess] = useState(null);

  // Function to get the token from cookies
  const getTokenFromCookies = () => {
    const cookieValue = document.cookie.split('; ').find(row => row.startsWith('x-auth-token='));
    return cookieValue ? cookieValue.split('=')[1] : null;
  };

  const token = getTokenFromCookies(); // Extract token from cookies

  // Define fetchUserProfileById with useCallback to avoid the warning
  const fetchUserProfileById = useCallback(async () => {
    try {
      const response = await axios.get(`${API_URL}/api/users/profile/${id}`, {
        headers: {
          'x-auth-token': token // Include token in the request header
        }
      });
      setUserProfileById(response.data);
    } catch (error) {
      console.error("Error fetching user profile:", error);
      setUserProfileById(null);
      toast.error('Failed to fetch user profile'); // Show error message
    } finally {
      setLoading(false); // Set loading to false after fetching
    }
  }, [id, token]); // Include 'id' and 'token' as dependencies

  useEffect(() => {
    fetchUserProfileById(); // Fetch user profile when component mounts
  }, [fetchUserProfileById]); // Include 'fetchUserProfileById' in the dependency array

  if (loading) {
    return (
      <div className="loader-container">
      <div className="loader"></div>
    </div>
    ); // Loader while fetching data
  }

  if (!userProfileById) {
    return <p>User profile not found.</p>;
  }

  // Check if userProfile is loaded and defined before accessing _id
  if (!userProfile) {
    return <div className="loader-container">
      <div className="loader"></div>
    </div>; // Optionally show a loading message
  }

  // Extract attendanceCounts from userProfileById
  const attendanceCounts = userProfileById.attendanceCounts || {
    present: 0,
    absent: 0,
    late: 0,
    "Absent(Informed)": 0,
  };

  // Calculate total attendance
  const totalAttendance =
    attendanceCounts.present +
    attendanceCounts.absent +
    attendanceCounts.late +
    attendanceCounts["Absent(Informed)"];

  // Calculate present percentage considering late and Absent(Informed) as present
  const presentPercentage = totalAttendance
    ? (((attendanceCounts.present + attendanceCounts.late + attendanceCounts["Absent(Informed)"]) / totalAttendance) * 100).toFixed(2)
    : 0;

  return (
    <section className="user-profile">
      <h1 className="heading">User Profile</h1>

      {isEditing ? (
        <UpdateProfileForm
          userProfile={userProfileById}
          userId={userProfileById._id}
          onClose={() => setIsEditing(false)}
          onUpdateSuccess={(message) => {
            setUpdateSuccess(message);
            setIsEditing(false);
            fetchUserProfileById(); // Refresh profile after update
          }}
          isAdmin={userProfile.role === 'admin'}
        />
      ) : (
        <div className="info">
          <div className="user">
            <img
              src={userProfileById.profilePic || 'https://cdn.pixabay.com/photo/2015/10/05/22/37/blank-profile-picture-973460_1280.png'}
              alt="Profile"
            />
            <h3>{userProfileById.name}</h3>
            <p>Role: {userProfileById.role}</p>
            <p>Gender: {userProfileById.gender}</p>
            <p>Date of Birth: {new Date(userProfileById.dateOfBirth).toLocaleDateString()}</p>

            {/* Show edit button if the user is viewing their own profile or has admin role */}
            {userProfile && (userProfile._id === userProfileById._id || userProfile.role === 'admin') && (
              <button onClick={() => setIsEditing(true)} className="inline-btn">
                <i className="fa-solid fa-pen-to-square"></i> Edit Profile
              </button>
            )}
          </div>

          {/* Profile Details and Links */}
          <div className="box-container">
            {(userProfileById.role === 'student') && (
              <div className="box">
                <div className="flex">
                  <i className="fa-solid fa-book"></i>
                  <div>
                    <span>{userProfileById.batch?.name}</span>
                    <p>{userProfileById.batch?.standard?.name}</p>
                  </div>
                </div>
              </div>
            )}

            {/* Fees Information (Admin View Only) */}
            {userProfile && userProfile.role === 'admin' && userProfileById.role === 'student' && (
              <div className="box">
                <div className="flex">
                  <i className="fa-solid fa-wallet"></i>
                  <div>
                    <span>Fees</span>
                    <p>Total: ₹{userProfileById.totalFee}</p>
                    <p>Pending: ₹{userProfileById.pendingFee}</p>
                    <p>Discount: ₹{userProfileById.discount}</p>
                  </div>
                </div>
                <Link to={`/loggedin/student/feepayments/${userProfileById._id}`} className="inline-btn">View Transactions</Link>
              </div>
            )}

            {userProfileById.role !== 'student' && (
              <div className="box">
                <div className="flex">
                  <i className="fa-solid fa-indian-rupee-sign"></i>
                  <div>
                    <span>Salary</span>
                    <p>Amount: ₹{userProfileById.salary}</p>
                    <p>Type: {userProfileById.salaryType}</p>
                  </div>
                </div>
                <Link to={`/loggedin/SalaryPaymentHistory/${userProfileById._id}`} className="inline-btn">View Salary Details</Link>
              </div>
            )}

            <div className="box">
              <div className="flex">
                <i className="fa-solid fa-phone"></i>
                <div>
                  <span>Contact</span>
                  <p>Personal: {userProfileById.personalContactNumber}</p>
                  <p>Emergency: {userProfileById.emergencyContactNumber}</p>
                </div>
              </div>
            </div>

            {userProfileById.role === 'student' && (
              <div className="box">
                <div className="flex">
                  <i className="fa-solid fa-user-group"></i>
                  <div>
                    <span>Guardian</span>
                    <p>Name: {userProfileById.parentName}</p>
                    <p>Relation: {userProfileById.relationshipToGuardian}</p>
                    <p>Contact: {userProfileById.parentContactNumber}</p>
                  </div>
                </div>
              </div>
            )}

            {(userProfileById.role === 'student' || userProfile.role === 'admin') && ( // Show attendance card if role is student or admin
              <div className="box">
                <div className="flex">
                  <i className="fas fa-calendar-check"></i>
                  <div>
                    <span>{presentPercentage}%</span>
                    <p>Attendance</p>
                  </div>
                </div>
                {userProfileById.role === 'student' ? (
                  <Link to={`/loggedin/student/attendance/${userProfileById._id}`} className="inline-btn">View Attendance</Link>
                ) : ''}
                {userProfileById.role !== 'student' ? (
                  <Link to={`/loggedin/staff/attendance/${userProfileById._id}`} className="inline-btn">View Attendance</Link>
                ) : ''}
              </div>
            )}

            {userProfileById.role === 'teacher' && (
              <div className="box">
                <div className="flex">
                  <i className="fas fa-chalkboard-teacher"></i>
                  <div>
                    <p>My batches</p>
                  </div>
                </div>
                <Link to={`/loggedin/manage-batches/${userProfileById._id}`} className="inline-btn">View Batches</Link>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Success Message */}
      {updateSuccess && <p className="success">{updateSuccess}</p>}
      <ToastContainer /> {/* Include the toast container for notifications */}
    </section>
  );
};

export default Profile;
