import React, { useState, useEffect } from "react";
import axios from "axios";
import Cookies from "js-cookie"; // Import the js-cookie library to manage cookies
import { useGlobal } from "../context/GlobalContext";
import {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Typography,
  CircularProgress,
  Box,
  Alert,
  Pagination,
} from "@mui/material";
import { useParams } from "react-router-dom"; // Import useParams from react-router-dom

const SalaryPaymentHistory = () => {
  const { API_URL } = useGlobal();
  const [salaryHistory, setSalaryHistory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [pagination, setPagination] = useState({ page: 1, limit: 10, totalPages: 0 });
  const { userId } = useParams(); // Access the userId from the URL parameters

  // Fetch salary payment history from the backend with pagination
  useEffect(() => {
    const fetchSalaryHistory = async () => {
      try {
        const token = Cookies.get("x-auth-token");

        const response = await axios.get(`${API_URL}/api/salary/salary-payment-history/${userId}`, {
          params: {
            page: pagination.page,
            limit: pagination.limit,
          },
          headers: {
            "x-auth-token": token,
          },
        });

        setSalaryHistory(response.data.data); // The data is now correctly accessed from the response
        setPagination({
          page: response.data.pagination.currentPage,
          limit: response.data.pagination.limit,
          totalPages: response.data.pagination.totalPages,
        });
        setLoading(false);
      } catch (error) {
        setError("Failed to fetch salary history.");
        setLoading(false);
      }
    };

    fetchSalaryHistory();
  }, [pagination.page, userId]); // Re-fetch data whenever page changes or userId changes

  const handlePageChange = (event, newPage) => {
    setPagination({ ...pagination, page: newPage });
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="100vh">
        <CircularProgress />
      </Box>
    );
  }

  if (error) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="100vh">
        <Alert severity="error">{error}</Alert>
      </Box>
    );
  }

  return (
    <Box padding="20px">
      <Typography variant="h4" gutterBottom>
        Salary Payment History
      </Typography>
      {salaryHistory.length === 0 ? (
        <Alert severity="info">No salary payment history available.</Alert>
      ) : (
        <TableContainer component={Paper}>
          <Table>
            <TableHead>
              <TableRow>
                <TableCell><strong>Paid Date (MM/YYYY)</strong></TableCell>
                <TableCell><strong>Total Days In Month</strong></TableCell>
                <TableCell><strong>Present Days</strong></TableCell>
                <TableCell><strong>Salary Amount</strong></TableCell>
                <TableCell><strong>Payment Method</strong></TableCell>
                <TableCell><strong>Status</strong></TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {salaryHistory.map((record, index) => (
                <TableRow key={index}>
                  <TableCell>{record.month} / {record.year}</TableCell>
                  <TableCell>{record.totalDaysInMonth}</TableCell>
                  <TableCell>{record.presentDays}</TableCell>
                  <TableCell>{record.salary}</TableCell>
                  <TableCell>{record.paymentMethod}</TableCell>
                  <TableCell>{record.status}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}
      <Box display="flex" justifyContent="center" mt={2}>
        <Pagination
          count={pagination.totalPages}
          page={pagination.page}
          onChange={handlePageChange}
          color="primary"
        />
      </Box>
    </Box>
  );
};

export default SalaryPaymentHistory;
