import React, { useRef } from "react";
import jsPDF from "jspdf";
import html2canvas from "html2canvas";
import { useGlobal } from '../context/GlobalContext';

const HallTicket = ({ testPaper }) => {
    const { userProfile } = useGlobal();
    const ticketRef = useRef();

    const handleDownload = async () => {
        const element = ticketRef.current;
        const canvas = await html2canvas(element);
        const imgData = canvas.toDataURL("image/png");
        const pdf = new jsPDF("p", "mm", "a4");
        const pdfWidth = pdf.internal.pageSize.getWidth();
        const pdfHeight = (canvas.height * pdfWidth) / canvas.width;
        pdf.addImage(imgData, "PNG", 0, 0, pdfWidth, pdfHeight);
        pdf.save("Hall_Ticket.pdf");
    };

    return (
        <div>
            <div
                ref={ticketRef}
                style={{
                    width: "800px",
                    margin: "auto",
                    padding: "20px",
                    border: "1px solid #000",
                    borderRadius: "5px",
                    backgroundColor: "#fff",
                    fontFamily: "Arial, sans-serif",
                }}
            >
                {/* Header */}
                <div style={{ textAlign: "center", marginBottom: "20px" }}>
                    <h2 style={{ margin: "0" }}>Excellence Coaching Classes</h2>
                    <h3 style={{ margin: "5px 0" }}>Hall Ticket</h3>
                </div>

                {/* Hall Ticket Info */}
                <div
                    style={{
                        display: "flex",
                        justifyContent: "space-between",
                        alignItems: "center",
                        border: "1px solid #000",
                        padding: "10px",
                        marginBottom: "10px",
                    }}
                >
                    <div>
                        <p>Student Id: <strong>{userProfile.studentId}</strong></p>
                        <p>Name: <strong>{userProfile.name}</strong></p>
                        <p>Date of Birth: <strong>{userProfile.dateOfBirth}</strong></p>
                        <p>Standard: <strong>{userProfile.batch.standard.name}</strong></p>
                        <p>Batch: <strong>{userProfile.batch.name}</strong></p>
                        <p>Emergency Contact Number: <strong>{userProfile.emergencyContactNumber}</strong></p>
                        <p>Address: <strong>{userProfile.address}</strong></p>
                    </div>
                    <div style={{ textAlign: "center" }}>
                        <img
                            src={userProfile.profilePic} // Add the student's photo URL if available
                            alt="Student Photo"
                            style={{
                                width: "100px",
                                height: "100px",
                                border: "1px solid #000",
                                marginBottom: "10px",
                            }}
                        />
                    </div>
                </div>

                {/* Exam Details */}
                <table style={{ width: "100%", borderCollapse: "collapse", marginBottom: "20px" }}>
                    <thead>
                        <tr>
                            <th style={{ border: "1px solid #000", padding: "5px" }}>Title</th>
                            <th style={{ border: "1px solid #000", padding: "5px" }}>Subject</th>
                            <th style={{ border: "1px solid #000", padding: "5px" }}>Date</th>
                            <th style={{ border: "1px solid #000", padding: "5px" }}>Start Time</th>
                            <th style={{ border: "1px solid #000", padding: "5px" }}>Total Marks</th>
                            <th style={{ border: "1px solid #000", padding: "5px" }}>Duration</th>
                        </tr>
                    </thead>
                    <tbody>
                        {testPaper.map((paper, index) => (
                            <tr key={index}>
                                <td style={{ border: "1px solid #000", padding: "5px" }}>{paper.title}</td>
                                <td style={{ border: "1px solid #000", padding: "5px" }}>{paper.subject}</td>
                                <td style={{ border: "1px solid #000", padding: "5px" }}>{new Date(paper.testDate).toLocaleDateString()}</td>
                                <td style={{ border: "1px solid #000", padding: "5px" }}>{paper.startTime}</td>
                                <td style={{ border: "1px solid #000", padding: "5px" }}>{paper.totalMarks}</td>
                                <td style={{ border: "1px solid #000", padding: "5px" }}>{paper.durationMinutes} minutes</td>
                            </tr>
                        ))}
                    </tbody>
                </table>

                {/* Signature Section */}
                <div style={{ display: "flex", justifyContent: "space-between", marginTop: "20px" }}>
                    <div style={{ textAlign: "center", width: "48%" }}>
                        <p>Student's Signature</p>
                        <div
                            style={{
                                borderTop: "1px solid #000",
                                width: "80%",
                                margin: "10px auto",
                                textAlign: "center",
                            }}
                        >
                            <p>____________________</p>
                        </div>
                    </div>
                    <div style={{ textAlign: "center", width: "48%" }}>
                        <p>Authority Signature</p>
                        <div
                            style={{
                                borderTop: "1px solid #000",
                                width: "80%",
                                margin: "10px auto",
                                textAlign: "center",
                            }}
                        >
                            <p>____________________</p>
                        </div>
                    </div>
                </div>

                {/* Instructions */}
                <div style={{ marginTop: "10px",marginLeft:'10px', fontSize: "12px" }}>
                    <h4>Important Instructions:</h4>
                    <ol>
                        <li>Candidates with an identity card and hall ticket will be admitted to the examination hall.</li>
                        <li>Reach the examination hall at least 30 minutes before the exam starts.</li>
                        <li>Mobile phones, smartwatches, and other electronic gadgets are strictly prohibited.</li>
                        <li>Carry your own stationery (pens, pencils, erasers, etc.).</li>
                        <li>Any form of cheating will result in immediate disqualification.</li>
                        <li>Do not write anything on the question paper other than your roll number.</li>
                        <li>Ensure your answers are marked properly and legibly in the answer sheet.</li>
                        <li>Maintain silence in the examination hall at all times.</li>
                        <li>Follow the invigilator's instructions without argument.</li>
                        <li>Leave the examination hall only after submitting your answer sheet to the invigilator.</li>
                    </ol>
                </div>
            </div>

            {/* Download Button */}
            <button
                onClick={handleDownload}
                style={{
                    marginTop: "20px",
                    padding: "10px 20px",
                    backgroundColor: "#007BFF",
                    color: "#fff",
                    border: "none",
                    borderRadius: "5px",
                    cursor: "pointer",
                }}
            >
                Download Hall Ticket
            </button>
        </div>
    );
};

export default HallTicket;
